files.app.art:
model Item {
  id: Number
  name: String
  amount: Number
  active: Bool
}

page Admin "/" {
  state page = "products"

  column gap=4 pad=4 {
    title "Panel" large
    Nav page=page onChange=(p => page = p)
    if page == "products" {
      ProductsPage
    } else if page == "customers" {
      CustomersPage
    } else if page == "orders" {
      OrdersPage
    } else if page == "suppliers" {
      SuppliersPage
    } else if page == "employees" {
      EmployeesPage
    } else if page == "categories" {
      CategoriesPage
    } else if page == "warehouses" {
      WarehousesPage
    } else if page == "invoices" {
      InvoicesPage
    } else if page == "coupons" {
      CouponsPage
    } else if page == "reviews" {
      ReviewsPage
    }
  }
}

component Nav(page: String, onChange: Fn) {
  row gap=2 wrap {
    button "Productos" primary=(page == "products") -> onChange("products")
    button "Clientes" primary=(page == "customers") -> onChange("customers")
    button "Pedidos" primary=(page == "orders") -> onChange("orders")
    button "Proveedores" primary=(page == "suppliers") -> onChange("suppliers")
    button "Empleados" primary=(page == "employees") -> onChange("employees")
    button "Categorías" primary=(page == "categories") -> onChange("categories")
    button "Depósitos" primary=(page == "warehouses") -> onChange("warehouses")
    button "Facturas" primary=(page == "invoices") -> onChange("invoices")
    button "Cupones" primary=(page == "coupons") -> onChange("coupons")
    button "Reseñas" primary=(page == "reviews") -> onChange("reviews")
  }
}

files.categories.art:
component CategoriesPage {
  state items: Item[] = [{ id: 1, name: "Alfa", amount: 10, active: true }, { id: 2, name: "Beta", amount: 20, active: true }, { id: 3, name: "Gama", amount: 30, active: false }]
  fn add(name, amount) {
    items.push({ id: Date.now(), name, amount, active: true })
  }

  column gap=2 {
    title "Categorías"
    CategoriesForm onAdd=add
    CategoriesList items=items
  }
}

component CategoriesList(items: Item[]) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        CategoriesRow item=item
      }
    }
  }
}

component CategoriesRow(item: Item) {
  row gap=2 {
    text item.name bold
    text `Margen: ${item.amount}`
  }
}

component CategoriesForm(onAdd: Fn) {
  state name = ""
  state amount = 0
  fn submit() {
    onAdd(name, amount)
    name = ""
    amount = 0
  }

  row gap=2 {
    input name placeholder="Nombre"
    input amount placeholder="Margen" type=number
    button "Agregar" primary -> submit()
  }
}

